pub fn parse(options_defs: Vec<OptionDef>, args: Vec<String>) -> Result<ParsedArgs, String> {
    let mut prepared: HashMap<String, usize> = HashMap::new();
    let mut opts = options_defs;

    // index by full and abbr
    for (i, opt) in opts.iter().enumerate() {
        prepared.insert(format!("--{}", opt.full), i);
        if let Some(abbr) = opt.abbr {
            prepared.insert(format!("-{}", abbr), i);
        }
        if opt.flag {
            prepared.insert(format!("--no-{}", opt.full), i);
        }
    }

    let mut parsed: HashMap<String, serde_json::Value> = HashMap::new();
    for opt in &opts {
        if let Some(ref default) = opt.default {
            if opt.flag {
                parsed.insert(opt.key.clone(), serde_json::Value::Bool(default == "true"));
            } else if opt.list {
                parsed.insert(opt.key.clone(), serde_json::Value::Array(vec![]));
            } else if opt.process.as_deref() == Some("number") {
                if let Ok(n) = default.parse::<i64>() {
                    parsed.insert(opt.key.clone(), serde_json::json!(n));
                } else {
                    parsed.insert(opt.key.clone(), serde_json::Value::String(default.clone()));
                }
            } else {
                parsed.insert(opt.key.clone(), serde_json::Value::String(default.clone()));
            }
        } else if opt.list {
            parsed.insert(opt.key.clone(), serde_json::Value::Array(vec![]));
        }
    }

    let mut positional: Vec<String> = vec![];
    let len = args.len();
    let mut i = 0;

    while i < len {
        let arg = &args[i];
        if arg.starts_with('-') {
            let (opt_name, value_part) = if let Some(eq_pos) = arg.find('=') {
                (arg[..eq_pos].to_string(), Some(arg[eq_pos + 1..].to_string()))
            } else {
                (arg.clone(), None)
            };

            // Check for --no- prefix
            let is_no = opt_name.starts_with("--no-");

            if let Some(&idx) = prepared.get(&opt_name) {
                // Known option
                let opt = &opts[idx];
                if let Some(ref cb) = opt.callback {
                    if cb == "version" {
                        return Err(format!("__version__"));
                    }
                    return Err(format!("__help__"));
                }

                if opt.flag {
                    let value = if is_no {
                        false
                    } else if let Some(ref vp) = value_part {
                        vp == "1" || vp == "true"
                    } else {
                        true
                    };
                    parsed.insert(opt.key.clone(), serde_json::Value::Bool(value));
                } else {
                    let value = if let Some(vp) = value_part {
                        vp
                    } else if i + 1 < len && !args[i + 1].starts_with('-') {
                        i += 1;
                        args[i].clone()
                    } else {
                        return Err(format!(
                            "Missing value: --{} requires a value\n\n---\n\n{}",
                            opt.full,
                            get_help_text(&opts)
                        ));
                    };

                    let processed = process_value(&value, &opt);
                    if opt.list {
                        if let Some(arr) = parsed.get_mut(&opt.key) {
                            if let Some(arr) = arr.as_array_mut() {
                                arr.push(processed);
                            }
                        }
                    } else {
                        parsed.insert(opt.key.clone(), processed);
                    }
                }
            } else {
                // Unknown option - pass through
                let real_name = opt_name
                    .trim_start_matches('-')
                    .trim_start_matches("no-");
                let is_flag = value_part.is_none()
                    && i + 1 < len
                    && args[i + 1].starts_with('-');

                if is_flag {
                    parsed.insert(real_name.to_string(), serde_json::Value::Bool(true));
                } else {
                    let value = if let Some(vp) = value_part {
                        vp
                    } else if i + 1 < len && !args[i + 1].starts_with('-') {
                        i += 1;
                        args[i].clone()
                    } else {
                        "true".to_string()
                    };
                    let processed: serde_json::Value =
                        serde_json::from_str(&value).unwrap_or(serde_json::Value::String(value));

                    if let Some(existing) = parsed.get_mut(real_name) {
                        if !existing.is_array() {
                            let old = existing.take();
                            let new_arr = if old == serde_json::Value::Bool(true) {
                                vec![]
                            } else {
                                vec![old]
                            };
                            *existing = serde_json::Value::Array(new_arr);
                        }
                        if let Some(arr) = existing.as_array_mut() {
                            arr.push(processed);
                        }
                    } else {
                        parsed.insert(real_name.to_string(), processed);
                    }
                }
            }
        } else {
            positional.push(if let Ok(n) = arg.parse::<i64>() {
                n.to_string()
            } else {
                arg.clone()
            });
        }
        i += 1;
    }

    // Validate choices
    for opt in &opts {
        if let Some(ref choices) = opt.choices {
            if let Some(val) = parsed.get(&opt.key) {
                let val_str = match val {
                    serde_json::Value::String(s) => s.clone(),
                    _ => val.to_string(),
                };
                if !choices.contains(&val_str) {
                    return Err(format!(
                        "Error: --{} must be one of the values {}\n\n---\n\n{}",
                        opt.full,
                        choices.join(","),
                        get_help_text(&opts)
                    ));
                }
            }
        }
    }

    Ok(ParsedArgs {
        options: parsed,
        positional,
    })
}

fn process_value(value: &str, opt: &OptionDef) -> serde_json::Value {
    match opt.process.as_deref() {
        Some("number") => {
            if let Ok(n) = value.parse::<i64>() {
                serde_json::json!(n)
            } else if let Ok(n) = value.parse::<f64>() {
                serde_json::json!(n)
            } else {
                serde_json::Value::String(value.to_string())
            }
        }
        Some("json") => {
            if let Ok(v) = serde_json::from_str::<serde_json::Value>(value) {
                v
            } else {
                // read from file
                if let Ok(contents) = std::fs::read_to_string(value) {
                    serde_json::from_str(&contents)
                        .unwrap_or(serde_json::Value::String(value.to_string()))
                } else {
                    serde_json::Value::String(value.to_string())
                }
            }
        }
        _ => {
            if let Ok(v) = serde_json::from_str::<serde_json::Value>(value) {
                v
            } else {
                serde_json::Value::String(value.to_string())
            }
        }
    }
}

pub fn get_help_text(opts: &[OptionDef]) -> String {
    let mut sorted: Vec<&OptionDef> = opts.iter().collect();
    sorted.sort_by_key(|o| o.display_index);

    let mut lines: Vec<String> = vec![];

    for opt in &sorted {
        let mut line = String::from("  ");
        if let Some(abbr) = opt.abbr {
            line.push_str(&format!("-{}, ", abbr));
        } else {
            line.push_str("    ");
        }

        if opt.flag {
            line.push_str(&format!("--(no-){}", opt.full));
        } else {
            line.push_str(&format!("--{}", opt.full));
        }

        if let Some(ref choices) = opt.choices {
            line.push_str(&format!("={}", choices.join("|")));
        } else if let Some(ref metavar) = opt.metavar {
            line.push_str(&format!("={}", metavar));
        }

        if opt.list {
            line.push_str(" ...");
        }

        if opt.default_help.is_some() || opt.default.is_some() || opt.help.is_some() {
            line.push_str("  ");
            if line.len() < 32 {
                line.push_str(&" ".repeat(32 - line.len()));
            }
            let text_len = line.len();
            if let Some(ref help) = opt.help {
                line.push_str(help);
            }
            if let Some(ref dh) = opt.default_help {
                if opt.help.is_some() {
                    line.push('\n');
                    line.push_str(&" ".repeat(text_len));
                }
                line.push_str(&format!("(default: {})", dh));
            } else if let Some(ref d) = opt.default {
                if opt.help.is_some() {
                    line.push('\n');
                    line.push_str(&" ".repeat(text_len));
                }
                line.push_str(&format!("(default: {})", d));
            }
        }

        lines.push(line);
    }

    format!(
        "\nUsage: jscodeshift [OPTION]... PATH...\n  \
         or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  \
         or:  jscodeshift [OPTION]... -t URL PATH...\n  \
         or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\n\
         Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.\n\
         If --stdin is set, each line of the standard input is used as a path.\n\n\
         Options:\n\
         \"...\" behind an option means that it can be supplied multiple times.\n\
         All options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n\
         {}\n",
        lines.join("\n")
    )
    .trim_start()
    .to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_basic() {
        let opts = define_options();
        let args: Vec<String> = vec![
            "-t".into(), "./transform.js".into(),
            "src/".into(),
        ];
        let result = parse(opts, args).unwrap();
        assert_eq!(result.positional, vec!["src/"]);
        assert_eq!(result.options["transform"], serde_json::json!("./transform.js"));
    }

    #[test]
    fn test_flag_option() {
        let opts = define_options();
        let args: Vec<String> = vec![
            "-t".into(), "./transform.js".into(),
            "--dry".into(),
            "src/".into(),
        ];
        let result = parse(opts, args).unwrap();
        assert_eq!(result.options["dry"], serde_json::json!(true));
    }

    #[test]
    fn test_no_flag() {
        let opts = define_options();
        let args: Vec<String> = vec![
            "-t".into(), "./transform.js".into(),
            "--no-babel".into(),
            "src/".into(),
        ];
        let result = parse(opts, args).unwrap();
        assert_eq!(result.options["babel"], serde_json::json!(false));
    }
}"}

{"command": "create", "path": "/workspace/jscodeshift-rust/src/files.rs", "file_text": "use ignore::gitignore::{Gitignore, GitignoreBuilder};
use std::path::Path;

pub struct IgnoreFiles {
    builder: GitignoreBuilder,
    matcher: Option<Gitignore>,
}

impl IgnoreFiles {
    pub fn new() -> Self {
        IgnoreFiles {
            builder: GitignoreBuilder::new("."),
            matcher: None,
        }
    }

    pub fn add(&mut self, pattern: &str) {
        if !pattern.is_empty() && !pattern.starts_with('#') {
            self.builder.add_line(None, pattern).ok();
        }
    }

    pub fn add_patterns(&mut self, patterns: &[String]) {
        for p in patterns {
            self.add(p);
        }
    }

    pub fn add_from_file(&mut self, path: &Path) {
        if path.is_file() {
            if let Ok(contents) = std::fs::read_to_string(path) {
                for line in contents.lines() {
                    self.add(line);
                }
            }
        }
    }

    fn ensure_built(&mut self) {
        if self.matcher.is_none() {
            self.matcher = Some(self.builder.build().unwrap_or_else(|_| {
                GitignoreBuilder::new(".").build().unwrap()
            }));
        }
    }

    pub fn should_ignore(&mut self, path: &str) -> bool {
        self.ensure_built();
        if let Some(ref matcher) = self.matcher {
            let matched = matcher.matched(path_or_dir, false);

            let normalized = path
                .trim_start_matches("./")
                .trim_start_matches("../");

            if !matched.is_ignore() && normalized != path {
                let normalized_matched = matcher.matched(normalized, false);
                normalized_matched.is_ignore()
            } else {
                matched.is_ignore()
            }
        } else {
            false
        }
    }
}

/// Discover all files in the given paths recursively, filtering by extension and ignore rules.
pub fn get_all_files(
    paths: &[String],
    extensions: &[String],
    ignores: &mut IgnoreFiles,
) -> Vec<String> {
    let mut files = vec![];
    for p in paths {
        collect_files(Path::new(p), extensions, ignores, &mut files);
    }
    files
}

fn collect_files(
    path: &Path,
    extensions: &[String],
    ignores: &mut IgnoreFiles,
    files: &mut Vec<String>,
) {
    if !path.exists() {
        eprintln!("Skipping path {} which does not exist.", path.display());
        return;
    }

    if path.is_dir() {
        if let Ok(entries) = std::fs::read_dir(path) {
            for entry in entries.flatten() {
                let entry_path = entry.path();
                let path_str = entry_path.to_string_lossy().to_string();

                if ignores.should_ignore(&path_str) {
                    continue;
                }

                if entry_path.is_dir() {
                    collect_files(&entry_path, extensions, ignores, files);
                } else if matches_extension(&path_str, extensions) {
                    files.push(path_str);
                }
            }
        }
    } else {
        let path_str = path.to_string_lossy().to_string();
        if ignores.should_ignore(&path_str) {
            return;
        }
        if matches_extension(&path_str, extensions) {
            files.push(path_str);
        }
    }
}

fn matches_extension(filename: &str, extensions: &[String]) -> bool {
    if extensions.is_empty() {
        return true;
    }
    extensions.iter().any(|ext| {
        if ext.starts_with('.') {
            filename.ends_with(ext.as_str())
        } else {
            filename.ends_with(&format!(".{}", ext))
        }
    })
}"}

{"command": "create", "path": "/workspace/jscodeshift-rust/src/runner.rs", "file_text": "use std::collections::HashMap;
use std::io::{BufRead, BufReader, Write};
use std::path::Path;
use std::process::{Child, Command, Stdio};
use std::time::Instant;

use crate::files::{get_all_files, IgnoreFiles};

const CHUNK_SIZE: usize = 50;

pub struct RunResult {
    pub ok: u64,
    pub nochange: u64,
    pub skip: u64,
    pub error: u64,
    pub stats: HashMap<String, u64>,
    pub time_elapsed: f64,
}

pub fn run(
    transform_file: &str,
    paths: Vec<String>,
    options: &HashMap<String, serde_json::Value>,
) -> Result<RunResult, String> {
    let cpus = {
        let requested = options.get("cpus").and_then(|v| v.as_i64()).unwrap_or(0) as usize;
        let available = std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1);
        let available = if available > 1 { available - 1 } else { 1 };
        if requested > 0 {
            requested.min(available)
        } else {
            available
        }
    };

    let extensions: Vec<String> = options
        .get("extensions")
        .and_then(|v| v.as_str())
        .unwrap_or("js,jsx,cjs,mjs,ts,tsx")
        .split(',')
        .map(|s| s.trim().to_string())
        .collect();

    let mut ignores = IgnoreFiles::new();

    if let Some(patterns) = options.get("ignorePattern") {
        if let Some(arr) = patterns.as_array() {
            for p in arr {
                if let Some(s) = p.as_str() {
                    ignores.add(s);
                }
            }
        }
    }

    if let Some(patterns) = options.get("ignoreConfig") {
        if let Some(arr) = patterns.as_array() {
            for p in arr {
                if let Some(s) = p.as_str() {
                    ignores.add_from_file(Path::new(s));
                }
            }
        }
    }

    if options
        .get("gitignore")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        let gitignore_path = std::env::current_dir()
            .unwrap_or_else(|_| Path::new(".").to_path_buf())
            .join(".gitignore");
        if gitignore_path.exists() {
            ignores.add_from_file(&gitignore_path);
        }
    }

    // Download URL transform if needed
    let transform_path = if transform_file.starts_with("http://")
        || transform_file.starts_with("https://")
    {
        download_transform(transform_file)?
    } else {
        let resolved = std::path::absolute(Path::new(transform_file))
            .map_err(|e| format!("Cannot resolve transform path: {}", e))?;
        if !resolved.exists() {
            return Err(format!(
                "ERROR Transform file {} does not exist",
                transform_file
            ));
        }
        resolved.to_string_lossy().to_string()
    };

    let files = get_all_files(&paths, &extensions, &mut ignores);

    if files.is_empty() {
        println!("No files selected, nothing to do.");
        return Ok(RunResult {
            ok: 0,
            nochange: 0,
            skip: 0,
            error: 0,
            stats: HashMap::new(),
            time_elapsed: 0.0,
        });
    }

    let num_files = files.len();
    let run_in_band = options
        .get("runInBand")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let silent = options
        .get("silent")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let processes = if run_in_band { 1 } else { cpus.min(num_files) };
    let chunk_size = if processes > 1 {
        (num_files / processes).min(CHUNK_SIZE).max(1)
    } else {
        num_files
    };

    if !silent {
        println!("Processing {} files...", num_files);
        if !run_in_band && processes > 1 {
            println!("Spawning {} workers...", processes);
        }
        if options
            .get("dry")
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
        {
            println!("Running in dry mode, no files will be written!");
        }
    }

    let start_time = Instant::now();

    // Build bridge args
    let babel_flag = if options
        .get("babel")
        .and_then(|v| v.as_bool())
        .unwrap_or(true)
    {
        "babel"
    } else {
        "no-babel"
    };

    let bridge_path = std::env::current_dir()
        .unwrap_or_else(|_| Path::new(".").to_path_buf())
        .join("bridge")
        .join("transform-host.js");

    let bridge_path = bridge_path.to_string_lossy().to_string();

    let mut file_index = 0;
    let mut workers: Vec<WorkerHandle> = vec![];

    // Build the init message
    let init_msg = serde_json::json!({
        "type": "init",
        "args": {
            "transform": transform_path,
            "babel": babel_flag,
        }
    });

    for i in 0..processes {
        let files_chunk: Vec<String> = if i < processes {
            let end = (file_index + chunk_size).min(num_files);
            let chunk = files[file_index..end].to_vec();
            file_index = end;
            chunk
        } else {
            vec![]
        };

        if files_chunk.is_empty() {
            break;
        }

        let mut child = Command::new("node")
            .arg(&bridge_path)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()
            .map_err(|e| format!("Failed to spawn worker: {}", e))?;

        // Send init
        let mut init = serde_json::to_string(&init_msg).unwrap();
        init.push('\n');
        if let Some(ref mut stdin) = child.stdin {
            stdin.write_all(init.as_bytes()).ok();
        }

        // Send first batch
        let options_clone = options.clone();
        let work_msg = serde_json::json!({
            "type": "files",
            "files": &files_chunk,
            "options": options_clone,
        });
        let mut msg = serde_json::to_string(&work_msg).unwrap();
        msg.push('\n');
        if let Some(ref mut stdin) = child.stdin {
            stdin.write_all(msg.as_bytes()).ok();
            stdin.flush().ok();
        }

        // Read ready from worker
        let stdout = child.stdout.take().expect("worker stdout");
        let reader = BufReader::new(stdout);

        workers.push(WorkerHandle {
            child,
            reader,
            pending: files_chunk.len(),
            done: false,
        });
    }

    let mut file_counters: HashMap<String, u64> = [
        ("ok".to_string(), 0),
        ("nochange".to_string(), 0),
        ("skip".to_string(), 0),
        ("error".to_string(), 0),
    ]
    .into();
    let mut stats_counter: HashMap<String, u64> = HashMap::new();

    // Poll workers round-robin
    let mut buf = String::new();
    loop {
        let mut all_done = true;
        let mut any_active = false;

        for wh in workers.iter_mut() {
            if wh.done {
                continue;
            }
            any_active = true;

            // Check if this worker has output
            buf.clear();
            match wh.reader.read_line(&mut buf) {
                Ok(0) => {
                    // EOF - worker exited
                    wh.done = true;
                    continue;
                }
                Ok(_) => {
                    let trimmed = buf.trim();
                    if trimmed.is_empty() {
                        continue;
                    }
                    if let Ok(msg) = serde_json::from_str::<serde_json::Value>(trimmed) {
                        match msg["action"].as_str() {
                            Some("status") => {
                                let status = msg["status"].as_str().unwrap_or("");
                                if let Some(counter) = file_counters.get_mut(status) {
                                    *counter += 1;
                                }
                                let msg_str = msg["msg"].as_str().unwrap_or("");
                                let verbose = options
                                    .get("verbose")
                                    .and_then(|v| v.as_i64())
                                    .unwrap_or(0);
                                log_status(status, msg_str, verbose);
                            }
                            Some("update") => {
                                let name = msg["name"].as_str().unwrap_or("");
                                let qty = msg["quantity"].as_u64().unwrap_or(1);
                                *stats_counter.entry(name.to_string()).or_insert(0) += qty;
                            }
                            Some("free") => {
                                // Send next chunk
                                let end = (file_index + chunk_size).min(num_files);
                                if file_index < num_files {
                                    if !silent && !run_in_band {
                                        println!(
                                            "Sending {} files to free worker...",
                                            (end - file_index)
                                        );
                                    }
                                    let chunk: Vec<&str> =
                                        files[file_index..end].iter().map(|s| s.as_str()).collect();
                                    file_index = end;
                                    let msg = serde_json::json!({
                                        "type": "files",
                                        "files": chunk,
                                        "options": options,
                                    });
                                    let mut out = serde_json::to_string(&msg).unwrap();
                                    out.push('\n');
                                    if let Some(ref mut stdin) = wh.child.stdin {
                                        stdin.write_all(out.as_bytes()).ok();
                                        stdin.flush().ok();
                                    }
                                } else {
                                    // No more files - send shutdown signal
                                    let msg = serde_json::json!({"type": "shutdown"});
                                    let mut out = serde_json::to_string(&msg).unwrap();
                                    out.push('\n');
                                    if let Some(ref mut stdin) = wh.child.stdin {
                                        stdin.write_all(out.as_bytes()).ok();
                                        stdin.flush().ok();
                                    }
                                    wh.done = true;
                                }
                            }
                            Some("report") => {
                                let file = msg["file"].as_str().unwrap_or("");
                                let report_msg = msg["msg"].as_str().unwrap_or("");
                                eprintln!(" REP {} {}", file, report_msg);
                            }
                            _ => {}
                        }
                    }
                }
                Err(_) => {
                    wh.done = true;
                    continue;
                }
            }

            if !wh.done {
                all_done = false;
            }
        }

        if !any_active {
            break;
        }
        if all_done {
            // Double-check all workers have exited
            let mut truly_done = true;
            for wh in workers.iter_mut() {
                if let Ok(Some(status)) = wh.child.try_wait() {
                    if !status.success() {
                        eprintln!("Worker exited with error: {:?}", status);
                    }
                    wh.done = true;
                } else {
                    truly_done = false;
                }
            }
            if truly_done {
                break;
            }
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }

    let elapsed = start_time.elapsed().as_secs_f64();

    if !silent {
        println!("All done.");
        println!(
            "Results:\n{} errors\n{} unmodified\n{} skipped\n{} ok",
            file_counters.get("error").unwrap_or(&0),
            file_counters.get("nochange").unwrap_or(&0),
            file_counters.get("skip").unwrap_or(&0),
            file_counters.get("ok").unwrap_or(&0),
        );
        if !stats_counter.is_empty() {
            let mut keys: Vec<&String> = stats_counter.keys().collect();
            keys.sort();
            for name in keys {
                println!("{}: {}", name, stats_counter[name]);
            }
        }
        println!("Time elapsed: {:.3}seconds", elapsed);
    }

    Ok(RunResult {
        ok: file_counters.get("ok").copied().unwrap_or(0),
        nochange: file_counters.get("nochange").copied().unwrap_or(0),
        skip: file_counters.get("skip").copied().unwrap_or(0),
        error: file_counters.get("error").copied().unwrap_or(0),
        stats: stats_counter,
        time_elapsed: elapsed,
    })
}

struct WorkerHandle {
    child: Child,
    reader: BufReader<std::process::ChildStdout>,
    pending: usize,
    done: bool,
}

fn download_transform(url: &str) -> Result<String, String> {
    let response = ureq::get(url)
        .call()
        .map_err(|e| format!("Failed to download transform: {}", e))?;
    let body = response
        .into_string()
        .map_err(|e| format!("Failed to read transform body: {}", e))?;

    let ext = Path::new(url)
        .extension()
        .map(|e| format!(".{}", e.to_string_lossy()))
        .unwrap_or_else(|| ".js".to_string());

    let tmp_dir = std::env::temp_dir();
    let file_path = tmp_dir.join(format!("jscodeshift_{}{}", rand_suffix(), ext));
    std::fs::write(&file_path, body)
        .map_err(|e| format!("Failed to write temp transform file: {}", e))?;
    Ok(file_path.to_string_lossy().to_string())
}

fn rand_suffix() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let dur = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    format!("{:x}", dur.as_nanos())
}

fn log_status(status: &str, msg: &str, verbose: i64) {
    match status {
        "ok" if verbose >= 2 => println!(" OKK {}", msg),
        "nochange" if verbose >= 1 => println!(" NOC {}", msg),
        "skip" if verbose >= 1 => println!(" SKIP {}", msg),
        "error" if verbose >= 0 => eprintln!(" ERR {}", msg),
        _ => {}
    }
}"}

