'use strict';

const fs = require('fs');
const path = require('path');
const readline = require('readline');

const j = require('../src/core');
const Runner = require('../src/Runner');

let initialized = false;
let transformPath = null;
let useBabel = true;

const rl = readline.createInterface({
  input: process.stdin,
  terminal: false,
});

process.on('uncaughtException', (err) => {
  respond({ action: 'free', error: true });
  console.error('Worker error:', err.message);
});

process.on('unhandledRejection', (reason) => {
  respond({ action: 'free', error: true });
  console.error('Worker rejection:', reason);
});

function respond(data) {
  process.stdout.write(JSON.stringify(data) + '\n');
}

// Pre-process a single file
function processFile(filePath, transform, options) {
  try {
    const fileInfo = new Runner.File(filePath, options);
    fileInfo.process(transform, j);
    return fileInfo;
  } catch (err) {
    const fileInfo = new Runner.File(filePath, options);
    fileInfo.error = { msg: err.message, err };
    fileInfo.status = 'error';
    return fileInfo;
  }
}

async function handleInit(rawArgs) {
  transformPath = rawArgs.transform;
  useBabel = rawArgs.babel !== 'no-babel';

  if (transformPath.startsWith('http://') || transformPath.startsWith('https://')) {
    // Should already be downloaded by Rust side, but handle if not
  } else {
    transformPath = path.resolve(transformPath);
  }

  initialized = true;
  respond({ action: 'ready' });
}

function handleFiles(files, options) {
  if (!initialized) {
    respond({ action: 'free', error: true });
    return;
  }

  const transformOptions = buildTransformOptions(transformPath, useBabel, options);

  let transform;
  try {
    transform = require(transformPath).__esModule
      ? require(transformPath).default || require(transformPath)
      : require(transformPath);
  } catch (e) {
    for (const file of files) {
      respond({
        action: 'status',
        status: 'error',
        msg: `${file}`,
        file: file,
      });
      respond({
        action: 'report',
        file: file,
        msg: `Transform error: ${e.message}`,
      });
    }
    respond({ action: 'free' });
    return;
  }

  for (const file of files) {
    const stat = processFile(file, transform, transformOptions);
    if (stat.status === 'ok' || stat.status === 'nochange') {
      respond({
        action: 'status',
        status: stat.status,
        msg: `${file}`,
      });

      if (stat.stats) {
        for (const [name, qty] of Object.entries(stat.stats)) {
          respond({
            action: 'update',
            name,
            quantity: qty,
          });
        }
      }
    } else {
      respond({
        action: 'status',
        status: stat.status || stat.status,
        msg: `${file}`,
      });

      if (stat.error) {
        respond({
          action: 'report',
          file: file,
          msg: stat.error.msg || 'Unknown error',
        });
      }
    }
  }

  // Clear require cache for the transform so it can be reloaded
  if (transformPath) {
    delete require.cache[require.resolve(transformPath)];
  }

  respond({ action: 'free' });
}

function buildTransformOptions(transformPath, babel, cliOptions) {
  const opts = { ...cliOptions };

  const extensions = opts.extensions || 'js,jsx,cjs,mjs,ts,tsx';
  opts.extensions = typeof extensions === 'string'
    ? extensions.split(',').map(s => s.trim()).filter(Boolean)
    : extensions;

  return opts;
}

async function main() {
  for await (const line of rl) {
    if (!line.trim()) continue;
    let msg;
    try {
      msg = JSON.parse(line);
    } catch (e) {
      continue;
    }

    switch (msg.type) {
      case 'init':
        handleInit(msg.args);
        break;
      case 'files':
        handleFiles(msg.files, msg.options || {});
        break;
      case 'shutdown':
        process.exit(0);
        break;
      default:
        respond({ action: 'unknown', type: msg.type });
    }
  }
}

main().catch((err) => {
  console.error('Bridge fatal error:', err);
  process.exit(1);
});"}

