      /\/recast\//,
      /\/ast-types\//,
    ],
  });
}

// ---- Transform loading ----
function loadTransform(tr, babel) {
  // Clear previous cache
  if (transformPath) {
    try { delete require.cache[require.resolve(transformPath)]; } catch (_) {}
  }

  if (babel === 'babel') {
    setupBabel(tr);
  } else {
    // Remove babel register
    const Module = require('module');
    const originalJS = Module._extensions['.js'];
    const originalJSX = Module._extensions['.jsx'];
    const originalTS = Module._extensions['.ts'];
    const originalTSX = Module._extensions['.tsx'];
    // Restore default extensions — babel register modifies them
    delete require.cache[require.resolve('@babel/register')];
    // We just don't re-register babel, effectively falling through to Node's built-in
  }

  // Delete require cache for the transform so it can be reloaded
  ['', '.js', '.ts', '.tsx', '.mjs', '.cjs'].forEach(ext => {
    try { delete require.cache[require.resolve(tr + ext)]; } catch (_) {}
  });

