// ---- jscodeshift preparation ----
function prepareJscodeshift(options) {
  const parser =
    parserFromTransform || getParser(options.parser, options.parserConfig);
  const core = require('../original/src/core');
  return core.withParser(parser);
}

// ---- File processing ----
function processFile(filePath, transform, options) {
  return new Promise((resolve) => {
    fs.readFile(filePath, (err, source) => {
      if (err) {
        resolve({ status: 'error', msg: filePath, report: 'File error: ' + err.message });
        return;
      }
      source = source.toString();
      try {
        const jscodeshift = prepareJscodeshift(options);
