          j: jscodeshift,
          jscodeshift: jscodeshift,
          stats: options.dry
            ? (name, qty) => {
                respond({
                  action: 'update',
                  name: name,
                  quantity: typeof qty !== 'number' ? 1 : qty,
                });
              }
            : () => {},
          report: (msg) => {
            respond({ action: 'report', file: filePath, msg: msg });
          },
        };

        const out = transform(fileInfo, api, options);

        if (out === undefined) {
          out = Promise.resolve(undefined);
        }

        Promise.resolve(out)
          .then((result) => {
            if (!result || result === source) {
              resolve({
                status: result ? 'nochange' : 'skip',
                msg: filePath,
              });
              return;
