                err.message.replace(/\n/g, ' ') +
                ')\n' +
                trimStackTrace(err.stack),
            });
          });
      } catch (err) {
        resolve({
          status: 'error',
          msg: filePath,
          report:
            'Transformation error (' +
            err.message.replace(/\n/g, ' ') +
            ')\n' +
            trimStackTrace(err.stack),
        });
      }
    });
  });
}

function trimStackTrace(trace) {
  if (!trace) return '';
  const lines = trace.split('\n');
  const result = [];
  lines.every((line) => {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

// ---- IPC message handlers ----
function handleInit(rawArgs) {
  transformPath = path.resolve(rawArgs.transform);
  babelMode = rawArgs.babel || 'babel';
  initialized = true;
  respond({ action: 'ready' });
}

async function handleFiles(files, options) {
  if (!initialized) {
    respond({ action: 'free' });
    return;
  }

  if (!transformFn) {
    try {
      transformFn = loadTransform(transformPath, babelMode);
    } catch (e) {
      for (const file of files) {
        respond({ action: 'status', status: 'error', msg: file });
        respond({ action: 'report', file: file, msg: 'Transform load error: ' + e.message });
      }
      respond({ action: 'free' });
      return;
    }
  }

  let i = 0;
  function next() {
    if (i >= files.length) {
      respond({ action: 'free' });
      return;
    }
    const file = files[i++];
    processFile(file, transformFn, options).then((result) => {
      respond({ action: 'status', status: result.status, msg: result.msg });
      if (result.report) {
        respond({ action: 'report', file: file, msg: result.report });
      }
      setImmediate(next);
    });
  }
  next();
}

