const rl = readline.createInterface({
  input: process.stdin,
  terminal: false,
});

async function main() {
  for await (const line of rl) {
    if (!line.trim()) continue;
    let msg;
    try { msg = JSON.parse(line); } catch (_) { continue; }

    switch (msg.type) {
      case 'init':
        handleInit(msg.args);
        break;
      case 'files':
        handleFiles(msg.files, msg.options || {});
        break;
      case 'shutdown':
        process.exit(0);
        break;
      default:
        respond({ action: 'unknown', type: msg.type });
    }
  }
}

