                        stdin.write_all(out.as_bytes()).ok();
                        stdin.flush().ok();
                    } else {
                        let _ = stdin.write_all(b"{\"type\":\"shutdown\"}\n");
                        stdin.flush().ok();
                        break;
                    }
                }

                // Forward everything to the main thread
                tx.send(trimmed).ok();
            }

            // Drain process
            let _ = child.wait();
        });

        handles.push(handle);
    }

    // Drop the original sender so the channel closes when all workers finish
    drop(tx);

    let mut file_counters: HashMap<String, u64> = [
        ("ok".to_string(), 0),
        ("nochange".to_string(), 0),
        ("skip".to_string(), 0),
        ("error".to_string(), 0),
    ]
    .into();
    let mut stats_counter: HashMap<String, u64> = HashMap::new();

    for line in rx {
        if let Ok(msg) = serde_json::from_str::<serde_json::Value>(&line) {
            match msg["action"].as_str() {
                Some("status") => {
                    let status = msg["status"].as_str().unwrap_or("");
                    if let Some(counter) = file_counters.get_mut(status) {
                        *counter += 1;
                    }
                    let msg_str = msg["msg"].as_str().unwrap_or("");
                    let verbose = options
                        .get("verbose")
                        .and_then(|v| v.as_i64())
                        .unwrap_or(0);
                    log_status(status, msg_str, verbose);
                }
                Some("update") => {
                    let name = msg["name"].as_str().unwrap_or("");
                    let qty = msg["quantity"].as_u64().unwrap_or(1);
                    *stats_counter.entry(name.to_string()).or_insert(0) += qty;
                }
                Some("report") => {
                    let file = msg["file"].as_str().unwrap_or("");
                    let report_msg = msg["msg"].as_str().unwrap_or("");
                    eprintln!(" REP {} {}", file, report_msg);
                }
                Some("print") => {
                    if let Some(content) = msg["content"].as_str() {
                        println!("{}", content);
                    }
                }
                _ => {}
            }
        }
    }

    // Wait for all worker threads
    for h in handles {
        h.join().ok();
    }"}

